def countTriangles(sides):
    s = sorted(sides)
    n = len(s)
    count = 0
    for k in range(2, n):
        i, j = 0, k - 1
        while i < j:
            if s[i] + s[j] > s[k]:
                count += j - i
                j -= 1
            else:
                i += 1
    return count
